// The skall tuvali's icon families (docs/design/sistem/uretec/lib.cjs → I: line icons, B: two-tone
// bar icons) → apps/mobile/src/theme/canvasIcons.generated.ts, drawn by
// apps/mobile/src/components/CanvasIcon.tsx. `node --experimental-strip-types
// scripts/sistem/icons.ts`; the test (icons.test.ts) checks the generated file against the canvas.
import { writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { join } from 'node:path';

type Lib = { I: Record<string, string>; B: Record<string, string> };

export function iconsSource(root: string): string {
  const lib = createRequire(import.meta.url)(
    join(root, 'docs/design/sistem/uretec/lib.cjs'),
  ) as Lib;
  const block = (name: string, family: Record<string, string>) =>
    `export const ${name} = {\n${Object.keys(family)
      .sort()
      .map((k) => `  ${JSON.stringify(k)}: ${JSON.stringify(family[k])},`)
      .join('\n')}\n} as const;\n`;
  return `// Generated by scripts/sistem/icons.ts from the skall tuvali (docs/design/sistem/uretec/lib.cjs).\n// Do not edit; run the script.\n${block('CANVAS_LINE', lib.I)}\n${block('CANVAS_BAR', lib.B)}`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const root = process.cwd();
  writeFileSync(join(root, 'apps/mobile/src/theme/canvasIcons.generated.ts'), iconsSource(root));
}
